// Generated by nocturne/build from nocturne/palette.toml. Edit that file, not this one.
// Linked into the Zen profile as user.js; Zen applies these at every start.
// Only appearance settings live here, so your other Zen settings stay yours.

// Load userChrome.css and userContent.css from the profile's chrome folder.
user_pref("toolkit.legacyUserProfileCustomizations.stylesheets", true);

// Dark window, the Nocturne accent, and the desktop's 10 px object radius.
user_pref("zen.view.window.scheme", 0);
user_pref("zen.theme.accent-color", "{{accent}}");
user_pref("zen.theme.border-radius", 10);
user_pref("zen.theme.content-element-separation", 8);

// The desktop's fonts for pages that do not choose their own.
user_pref("font.name.sans-serif.x-western", "IBM Plex Sans");
user_pref("font.name.serif.x-western", "IBM Plex Serif");
user_pref("font.name.monospace.x-western", "Lilex Nerd Font Mono");
